param([string]$RepoRoot='C:\Users\aaron\Desktop\URAP',[string]$RunId='sam2p1_large_download_v1')
$root=Join-Path $RepoRoot 'artifacts\detached_sam2p1_large_download_v1';$pidFile=Join-Path $root ($RunId+'.pid');$metaFile=Join-Path $root ($RunId+'.meta.json');$pidValue=if(Test-Path $pidFile){[int](Get-Content $pidFile|Select-Object -First 1)}else{0};$process=if($pidValue){Get-CimInstance Win32_Process -Filter "ProcessId=$pidValue" -ErrorAction SilentlyContinue}else{$null};$meta=if(Test-Path $metaFile){Get-Content $metaFile -Raw|ConvertFrom-Json}else{$null};$final=if($meta -and (Test-Path $meta.destination)){Get-Item $meta.destination}else{$null};$partial=if($meta -and (Test-Path $meta.partial)){Get-Item $meta.partial}else{$null};$paths=if($meta){@($meta.stdout,$meta.stderr,$meta.destination,$meta.partial)|Where-Object{Test-Path $_}}else{@()};$latest=$paths|%{Get-Item $_}|Sort-Object LastWriteTime -Descending|Select-Object -First 1
Write-Output "status: $(if($process){'RUNNING'}else{'NOT RUNNING'})";Write-Output "done/total: $(if($final){'1/1'}else{'0/1'})";Write-Output "stage: $(if($final){'download_complete'}elseif($process){'downloading'}else{'not_started_or_failed'})";Write-Output "pid: $pidValue";Write-Output "start_time: $(if($meta){$meta.started}else{'unknown'})";if($process){Write-Output "command: $($process.CommandLine)"};Write-Output "last_output_timestamp: $(if($latest){$latest.LastWriteTime}else{'none'})";Write-Output "last_completed_unit: $(if($final){'sam2.1_hiera_large.pt'}elseif($partial){'partial_bytes='+$partial.Length}else{'none'})";Write-Output 'gpu_signal: NOT APPLICABLE';Write-Output "stdout: $($meta.stdout)";Write-Output "stderr: $($meta.stderr)";Write-Output "destination: $($meta.destination)"
